<template>
  <div>
    <label for="color">Color</label>
    <custom-color
      v-model="newSettings.color"
      @input="$emit('updateLayer', this.newSettings)"
    />
  </div>
  <div>
    <label>Width: {{ newSettings.width }}</label>
    <custom-range
      v-model="newSettings.width"
      @input="$emit('updateLayer', this.newSettings)"
      :step="1"
      :min="1"
      :max="100"
    />
  </div>
  <div>
    <label>Separated Size</label>
    <Toggle v-model="newSettings.size.separated" />
  </div>
  <div v-if="!newSettings.size.separated">
    <label>Size: {{ newSettings.size.y }}</label>
    <custom-range
      v-model="newSettings.size.y"
      @input="$emit('updateLayer', this.newSettings)"
      :step="0.1"
      :min="0.1"
      :max="200"
    />
  </div>
  <div v-else>
    <div>
      <label>Vertical Size: {{ newSettings.size.y }}</label>
      <custom-range
        v-model="newSettings.size.y"
        @input="$emit('updateLayer', this.newSettings)"
        :step="0.1"
        :min="0.1"
        :max="200"
      />
    </div>
    <div>
      <label>Horizontal Size: {{ newSettings.size.x }}</label>
      <custom-range
        v-model="newSettings.size.x"
        @input="$emit('updateLayer', this.newSettings)"
        :step="0.1"
        :min="0.1"
        :max="200"
      />
    </div>
  </div>
  <div>
    <custom-fieldset title="Outline">
      <div>
        <label>Enable</label>
        <Toggle v-model="newSettings.outline.enabled" />
      </div>
      <div v-show="newSettings.outline.enabled">
        <div>
          <label for="color">Color</label>
          <custom-color
            v-model="newSettings.outline.color"
            @input="$emit('updateLayer', this.newSettings)"
          />
        </div>
        <div>
          <label>Width: {{ newSettings.outline.width }}</label>
          <custom-range
            v-model="newSettings.outline.width"
            @input="$emit('updateLayer', this.newSettings)"
            :step="1"
            :min="1"
            :max="100"
          />
        </div>
      </div>
    </custom-fieldset>
  </div>
  <div>
    <custom-fieldset title="Fill">
      <div>
        <label>Enable</label>
        <Toggle v-model="newSettings.fill.enabled" />
      </div>
      <div v-show="newSettings.fill.enabled">
        <div>
          <label for="color">Color</label>
          <custom-color
            v-model="newSettings.fill.color"
            @input="$emit('updateLayer', this.newSettings)"
          />
        </div>
      </div>
    </custom-fieldset>
  </div>
  <div>
    <custom-fieldset title="Offsets">
      <div>
        <label>Top: {{ newSettings.offset.top }}</label>
        <custom-range v-model="newSettings.offset.top" :min="-150" :max="150" />
      </div>
      <div>
        <label>Right: {{ newSettings.offset.right }}</label>
        <custom-range
          v-model="newSettings.offset.right"
          :min="-150"
          :max="150"
        />
      </div>
    </custom-fieldset>
  </div>
</template>

<script>
import CustomRange from "../../../../reusable/CustomRange.vue";
import CustomColor from "../../../../reusable/CustomColor.vue";
import CustomFieldset from "../../../../reusable/CustomFieldset.vue";
import Toggle from "@vueform/toggle";

export default {
  components: { CustomRange, Toggle, CustomFieldset, CustomColor },
  name: "circle-config",
  emits: ["updateLayer"],
  data() {
    return {
      newSettings: {},
    };
  },
  created() {
    this.newSettings = { ...this.setting };
  },
  props: {
    setting: {
      type: Object,
    },
  },
};
</script>

<style lang="scss" scoped>
div {
  display: flex;
  flex-direction: column;
  margin: 5px 0;
}

label {
  font-weight: bold;
}
</style>
