<template>
  <input
    type="range"
    :min="min"
    :max="max"
    :step="step"
    :value="modelValue"
    @input="$emit('update:modelValue', $event.target.value)"
  />
</template>

<script>
export default {
  name: "custom-range",
  props: {
    min: {
      default: "1",
    },
    max: {
      default: "100",
    },
    step: {
      default: "1",
    },
    modelValue: {},
  },
};
</script>

<style lang="scss" scoped>
input {
  background: transparent;
}

input[type="range"] {
  -webkit-appearance: none;
  width: 100%;
}
input[type="range"]:focus {
  outline: none;
}
input[type="range"]::-webkit-slider-runnable-track {
  width: 100%;
  height: 100%;
  cursor: pointer;
  background: darken($gray, 5%);
  border: 1px solid darken($gray, 8%);
  border-radius: 5px;
}
input[type="range"]::-webkit-slider-thumb {
  height: 25px;
  width: 20px;
  border-radius: 5px;
  background: rgba($blue, 0.5);
  cursor: pointer;
  -webkit-appearance: none;
}
</style>
