<template>
  <table>
    <thead>
      <tr>
        <th>Challenge</th>
        <th>Progress</th>
        <th>Expires</th>
      </tr>
    </thead>
    <tbody>
      <tr v-for="chal in devMode ? devChals : chals" :key="chal">
        <td>{{ chal.name }}</td>
        <td>{{ chal.progress }}</td>
        <td>{{ chal.expire === 0 ? "Expired" : countdown(chal.expire) }}</td>
      </tr>
    </tbody>
  </table>
</template>

<script>
export default {
  name: "ChallengesTab",
  props: ["devMode"],
  data() {
    return {
      chals: [],
      devChals: [
        { name: "Kill 5 fortnite noobs", progress: "2/5", expire: 15 },
        { name: "Fly hydra by admin abuse", progress: "0/1", expire: 500 },
        { name: "Fly jetpack", progress: "0/1", expire: 61 },
        {
          name: "Hold interior for 5 minutes",
          progress: "2/5",
          expire: 276480,
        },
      ],
    };
  },
  methods: {
    countdown(s) {
      const d = Math.floor(s / (3600 * 24));

      s -= d * 3600 * 24;

      const h = Math.floor(s / 3600);

      s -= h * 3600;

      const m = Math.floor(s / 60);

      s -= m * 60;

      const tmp = [];

      d && tmp.push(d + "d");

      (d || h) && tmp.push(h + "h");

      (d || h || m) && tmp.push(m + "m");

      tmp.push(s + "s");

      return tmp.join(" ");
    },
  },
  mounted() {
    setInterval(() => {
      this.chals.forEach((chal) => {
        if (chal.expire > 0) chal.expire--;
      });
    }, 1000);
  },
};
</script>

<style lang="scss" scoped>
table {
  font-family: Arial, Helvetica, sans-serif;
  border-collapse: separate;
  border: solid $gray 2px;
  border-radius: 15px;
  width: 100%;
  color: lighten($gray, 30%);
  border-radius: 15px;
  border-spacing: 0;
  background: $gray;
  font-weight: bold;

  tbody td:last-child,
  thead th:last-child {
    border-right: none;
  }

  & th:first-child {
    border-radius: 15px 0 0 15px;
  }

  & th:last-child {
    border-radius: 0 15px 15px 0;
  }
}

tbody {
  & tr:last-child {
    td {
      &:first-child {
        border-bottom-left-radius: 15px;
      }
      &:last-child {
        border-bottom-right-radius: 15px;
      }
    }
  }
}

table td,
th {
  padding: 8px;
}

table tr {
  background: $gray;
}

table tr:nth-child(even) {
  background-color: darken($gray, 2.5%);
}

table tr:hover {
  background-color: lighten($gray, 5%);
}

table th {
  padding-top: 12px;
  padding-bottom: 12px;
  text-align: left;
  background-color: rgb(65, 82, 116);
  color: $blue;
}
</style>
