<template>
  <div class="configBox">
    <div class="header">
      <div class="items">
        <i class="bx bx-align-left handle"></i>
        <i
          v-if="collapsed"
          class="fa-solid fa-square-plus collapse"
          @click="collapse"
        ></i>
        <i
          v-else
          class="fa-solid fa-square-minus collapse"
          @click="collapse"
        ></i>
        <i
          v-if="!setting.hidden"
          @click="toggleHide"
          class="fa-solid fa-eye hide"
        ></i>
        <i v-else @click="toggleHide" class="fa-solid fa-eye-slash hide"></i>
        <i class="fa-solid fa-clone clone" @click="cloneLayer"></i>
        <div class="title">
          <input
            type="text"
            @focus="toggleTyping(true)"
            @blur="toggleTyping(false)"
            @change="changeLayerName"
            :value="setting.name"
          />
        </div>
      </div>
      <i class="fa fa-times close" @click="$emit('removeLayer', index)"></i>
    </div>
    <div class="configs" v-show="!collapsed">
      <default-config
        v-if="setting.type === 1"
        @updateLayer="$emit('updateLayer', index, $event)"
        :setting="setting"
      />
      <circle-config
        v-if="setting.type === 2"
        @updateLayer="$emit('updateLayer', index, $event)"
        :setting="setting"
      />
    </div>
  </div>
</template>

<script>
import DefaultConfig from "./Types/Default/DefaultConfig.vue";
import CircleConfig from "./Types/Circle/CircleConfig.vue";
export default {
  components: { DefaultConfig, CircleConfig },
  name: "config-box",
  emits: ["removeLayer", "updateLayer", "cloneLayer"],
  methods: {
    cloneLayer() {
      let newSetting = JSON.parse(JSON.stringify(this.setting));
      newSetting.name = `${newSetting.name} Clone`;
      this.$emit("cloneLayer", newSetting);
    },
    toggleTyping(state) {
      // eslint-disable-next-line no-undef
      mp.trigger("MenuToggleTyping", state);
    },
    collapse() {
      this.collapsed = !this.collapsed;
    },
    toggleHide() {
      let newSetting = { ...this.setting };
      newSetting.hidden = !newSetting.hidden;
      this.$emit("updateLayer", this.index, newSetting);
    },
    changeLayerName(event) {
      let newSetting = { ...this.setting };
      newSetting.name = event.target.value;
      this.$emit("updateLayer", this.index, newSetting);
    },
  },
  props: {
    index: {
      type: Number,
    },
    setting: {
      type: Object,
    },
  },
  data() {
    return {
      collapsed: true,
    };
  },
};
</script>

<style lang="scss" scoped>
::selection {
  color: $blue;
  background: rgba($blue, 0.3);
}

.configBox {
  background: lighten($foreground, 10%);
  border-radius: 5px;
  padding: 10px;
  border: 2px solid rgba($blue, 0.3);
  color: $white-text;

  .header {
    display: flex;
    justify-content: space-between;
    align-items: center;

    .items {
      display: inline-flex;
      align-items: center;
      justify-content: flex-start;
      gap: 5px;

      .title {
        flex: 1.5;
        input {
          background: transparent;
          padding-left: 5px;
          width: 100%;

          &:focus {
            outline: 2px solid rgba($blue, 0.3);
            border-radius: 5px;
          }
        }
      }

      code {
        //OLD INDEX VIEWER
        background: lighten($background, 5%);
        font-size: 12px;
        padding: 2px 5px;
        border-radius: 5px;
        flex: 1;
      }
    }

    .close {
      height: 15px;
      width: 12px;
      display: flex;
      justify-content: center;
      align-items: center;
      &:hover {
        color: rgb(255, 158, 158);
      }
    }

    .handle {
      &:hover {
        color: $blue;
      }
    }

    .collapse {
      &:hover {
        color: $orange;
      }
    }

    .hide {
      width: 16px;
      display: flex;
      justify-content: center;
      align-items: center;
      &:hover {
        color: lightpink;
      }
    }

    .clone {
      &:hover {
        color: lightgreen;
      }
    }
  }
}
</style>
