<template>
  <div class="setting grid">
    <label :id="id">{{ label }}</label>
    <small class="mb-1">{{ description }}</small>
    <CustomSelect :preSelect="preSelect" :options="options" :id="`settings${name}`" @change="change" ref="select" />
  </div>
</template>

<script>
import CustomSelect from "../../../components/CustomSelect.vue";

export default {
  name: "SelectOption",
  props: ["id", "label", "name", "description", "options", "preSelect"],
  components: {
    CustomSelect,
  },
  data() {
    return {};
  },
  methods: {
    change(type) {
      // eslint-disable-next-line no-undef
      mp.trigger("MenuChangeSettings", this.id, type);
    },
  },
};
</script>

<style scoped lang="scss">
.setting {
  color: $white-text;

  small {
    color: $gray-text;
  }
}
</style>
