<template>
  <div
    class="crosshair"
    :style="{
      transform: `rotate(${settings.rotation}deg)`,
      marginRight: `${settings.offset.right}px`,
      marginTop: `${settings.offset.top}px`,
    }"
  >
    <div
      :style="{
        borderRadius: `${settings.radius}%`,
        background: settings.color,
        height: `${settings.size}px`,
        width: `${settings.width}px`,
        opacity: settings.sides[0] ? '1' : '0',
        border: settings.outline.enabled
          ? `solid ${settings.outline.width}px ${settings.outline.color}`
          : `none`,
      }"
      class="crosshair-top"
    ></div>
    <div class="flex items-center">
      <div
        :style="{
          borderRadius: `${settings.radius}%`,
          background: settings.color,
          width: `${settings.size}px`,
          height: `${settings.width}px`,
          opacity: settings.sides[1] ? '1' : '0',
          border: settings.outline.enabled
            ? `solid ${settings.outline.width}px ${settings.outline.color}`
            : `none`,
        }"
        class="crosshair-left"
        id="testfix"
      ></div>
      <div
        class="crosshair-dot"
        :style="{ height: `${settings.gap}px`, width: `${settings.gap}px` }"
      >
        <div
          v-if="settings.dot.enabled"
          :style="{
            borderRadius: `${settings.dot.radius}%`,
            background: settings.dot.color,
            height: `${settings.dot.size}px`,
            width: `${settings.dot.size}px`,
            border: settings.outline.enabled
              ? `solid ${settings.outline.width}px ${settings.outline.color}`
              : `none`,
          }"
        ></div>
      </div>
      <div
        :style="{
          borderRadius: `${settings.radius}%`,
          background: settings.color,
          width: `${settings.size}px`,
          height: `${settings.width}px`,
          opacity: settings.sides[2] ? '1' : '0',
          border: settings.outline.enabled
            ? `solid ${settings.outline.width}px ${settings.outline.color}`
            : `none`,
        }"
        class="crosshair-right"
      ></div>
    </div>
    <div
      :style="{
        borderRadius: `${settings.radius}%`,
        background: settings.color,
        height: `${settings.size}px`,
        width: `${settings.width}px`,
        opacity: settings.sides[3] ? '1' : '0',
        border: settings.outline.enabled
          ? `solid ${settings.outline.width}px ${settings.outline.color}`
          : `none`,
      }"
      class="default-bottom"
    ></div>
  </div>
</template>

<script>
export default {
  name: "DefaultType",
  props: ["settings"],
};
</script>

<style lang="scss" scoped>
.crosshair {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.crosshair-dot {
  overflow: visible;
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;

  div {
    position: absolute;
  }
}
</style>
